# Source for q/ae-views-measure2.js: Echo views (technique, troubleshooting) + Measurements (method) + Stress echo.
V="Echo views"; M="Measurements"; S="Stress echo"
Q=[
# --- Transducer movement and positioning ---
(V,"Rocking the transducer means:","Angling it within the imaging plane, toward or away from the marker",["Moving it to a new rib space","Spinning it around its long axis","Pressing harder"],"Rocking keeps the same plane but moves the structure across the screen.","F"),
(V,"Sliding the transducer means:","Moving the whole transducer to a new spot on the skin",["Turning it around its long axis","Angling it within the plane","Changing frequency"],"Sliding is used to find a better window or follow a structure.","F"),
(V,"Rotating the transducer:","Turns the imaging plane around the beam's axis without moving the contact point",["Moves it one rib space","Changes the frequency","Changes the depth"],"Rotation changes long-axis to short-axis views.","F"),
(V,"For the suprasternal notch view, positioning is improved by:","Placing a pillow under the shoulders and extending the neck, turning the head slightly",["Having the patient sit forward","Lying prone","Bending the neck forward"],"This opens the notch for the transducer.","F"),
(V,"For subcostal views, imaging is often improved by:","Having the patient lie supine with knees bent and take a deep breath in",["Having the patient stand","Lying on the right side","Breathing out fully and holding"],"Bending the knees relaxes the abdominal muscles; inspiration brings the heart down.","F"),
(V,"Holding the breath at end-expiration sometimes improves parasternal images because:","The lung moves away from the heart",["The heart moves to the right","Heart rate slows to zero","The diaphragm rises into the chest only"],"Lung tissue between the transducer and heart blocks the beam.","F"),
# --- View checks ---
(V,"An on-axis PSAX view at the papillary muscle level shows:","A round LV with both papillary muscles, at about 4 and 8 o'clock",["An oval LV with no muscles","The aortic valve","The left atrium"],"An oval LV means the plane is oblique.","F"),
(V,"The PSAX view at the apical level is recognized by:","A small round LV cavity without papillary muscles",["Mitral leaflets","Both papillary muscles","The aortic valve"],"Slide or tilt toward the apex from the papillary level.","F"),
(V,"In a well-aligned PLAX view, the LV apex is:","Usually not seen, and the septum and posterior wall are nearly horizontal and parallel",["Always seen at the top","Seen at the center","Replaced by the RV"],"If the apex is visible, the plane may be too low (oblique).","C"),
(V,"In a correct apical four-chamber view, the RV should be:","No more than about two-thirds of the LV width",["Larger than the LV","Not visible","The only ventricle seen"],"An RV larger than the LV suggests RV dilation if the view is correct.","F"),
(V,"In a standard apical two-chamber view, the wall on the left side of the screen is the:","Inferior wall",["Anterior wall","Lateral wall","Septum"],"The anterior wall is on the right side of the screen.","C"),
(V,"In a standard apical long-axis (three-chamber) view, the walls seen are:","Inferolateral (left of screen) and anteroseptal (right of screen)",["Inferior and anterior","Septal and lateral","Only the apex"],"It also shows the LVOT, aortic valve and mitral valve.","C"),
(V,"Which view shows the RV free wall, tricuspid valve and the RA with the coronary sinus and IVC entering?","Parasternal RV inflow view",["PLAX","Suprasternal view","Apical two-chamber view"],"The coronary sinus may be seen entering the RA near the tricuspid valve.","F"),
(V,"In the subcostal four-chamber view, the liver is seen:","In the near field, at the top of the screen",["Behind the heart","Not at all","On the right side of the screen only"],"The liver is the acoustic window.","F"),
(V,"The IVC in the subcostal long-axis view should be traced to show:","Its entry into the right atrium, with a hepatic vein joining near the junction",["The aortic valve","The pulmonary veins","The LV apex"],"Make sure it is not the aorta, which pulses and runs on the left side.","F"),
(V,"An easy way to tell the abdominal aorta from the IVC on subcostal imaging is that the aorta:","Pulses, has thicker walls, does not change with breathing, and does not enter the RA",["Collapses with sniffing","Drains into the RA","Is always larger than the IVC"],"Color and PW Doppler show arterial flow.","F"),
(V,"Increasing sector width without changing anything else will:","Lower the frame rate",["Raise the frame rate","Improve lateral resolution","Increase penetration"],"Narrow the sector to raise the frame rate for wall motion and color.","F"),
(V,"The correct imaging depth for an apical view should:","Just include the whole heart, often around 16 cm, then be reduced if possible",["Be 30 cm for all patients","Cut off the atria","Show only the apex"],"Extra depth lowers frame rate and wastes the image.","F"),
(V,"When the endocardium of two or more LV segments is not seen in apical views, the best next step is to:","Try harmonic imaging and adjust windows, then use an ultrasound enhancing agent",["Stop the exam","Increase depth to 25 cm","Use M-mode only"],"Contrast improves EF and wall motion accuracy.","F"),
(V,"An ECG trace should be recorded with every echo study mainly to:","Time measurements to the right point of the cardiac cycle",["Measure blood pressure","Check oxygen","Diagnose valve disease"],"End-diastole and end-systole are identified from the ECG and valve motion.","F"),
(V,"Recording a respiratory trace is useful when assessing:","Constrictive pericarditis or tamponade",["Bicuspid aortic valve","LV mass","Aortic root size"],"Variation must be matched to the breathing phase.","F"),
(V,"For measuring respiratory variation in mitral inflow, the sweep speed is usually set:","Slower (about 25 to 50 mm/s) to show several breaths",["Faster than 200 mm/s","At zero","Exactly 100 mm/s only"],"For single-beat measurements, use about 100 mm/s.","C"),
# --- Measurement timing and conventions ---
(M,"End-diastole for LV measurements is defined as:","The frame just after mitral valve closure, or the frame with the largest LV dimension",["The frame with the smallest LV","The T wave","Mitral valve opening"],"It is often at the peak of the R wave on the ECG.","F"),
(M,"End-systole for LV measurements is defined as:","The frame just before mitral valve opening, or the frame with the smallest LV cavity",["The QRS onset","The largest LV size","The P wave"],"Aortic valve closure marks the end of ejection.","F"),
(M,"For the biplane method of disks, papillary muscles and trabeculations should be:","Included in the LV cavity",["Included in the wall","Measured separately","Ignored by tracing through them randomly"],"Trace along the compact myocardium border.","F"),
(M,"In the biplane method, the LV lengths in the four- and two-chamber views should differ by:","Less than about 10%",["At least 50%","Exactly 2 cm","There is no rule"],"A large difference suggests foreshortening in one view.","C"),
(M,"For M-mode LV measurements from PLAX, the cursor should be placed:","Perpendicular to the LV long axis at the mitral leaflet tips",["Through the aortic valve","At the apex","At an angle through the papillary muscles"],"An oblique cursor overestimates dimensions.","F"),
(M,"For PW Doppler of mitral inflow (E and A waves), the sample volume is placed:","At the mitral leaflet tips, with a 1–3 mm sample",["At the mitral annulus","In the LA","In the LVOT"],"Annulus placement is used for mitral stroke volume.","F"),
(M,"Pulmonary vein PW Doppler sample volume should be placed:","About 1 to 2 cm into the vein",["In the LA cavity","At the mitral tips","In the LAA"],"Color helps locate the vein in the apical four-chamber view.","F"),
(M,"For tissue Doppler of the mitral annulus, settings should include:","A sample of about 5–10 mm at the annulus, low gain and filter, and a low velocity scale",["High wall filter and high gain","A 1 mm sample in the LA","The highest velocity scale"],"Keep the beam aligned with annular motion (under about 20°).","C"),
(M,"Speckle-tracking strain needs a frame rate of about:","40 to 90 frames per second",["5 frames per second","300 frames per second","1 frame per second"],"Too low misses peaks; too high loses spatial resolution.","C"),
(M,"Speckle-tracking strain timing is usually based on:","Aortic valve closure to define end-systole",["P-wave onset","The T wave","Mitral valve opening"],"Mark aortic closure from the apical long-axis view or LVOT Doppler.","C"),
(M,"TAPSE is measured using:","M-mode through the lateral tricuspid annulus in the RV-focused apical view",["2D from PLAX","PW Doppler at the tricuspid tips","M-mode through the aortic valve"],"Align the cursor with the direction of annular motion.","F"),
(M,"RV fractional area change is calculated as:","(RV end-diastolic area − end-systolic area) ÷ end-diastolic area",["TAPSE ÷ RV length","RV volume ÷ LV volume","PASP ÷ TAPSE"],"Trabeculations are included in the cavity when tracing.","F"),
(M,"Right atrial area is measured:","At end-systole in the apical four-chamber view",["At end-diastole in PLAX","At mid-diastole in subcostal","Only with TEE"],"This is when the RA is largest.","F"),
(M,"The LVOT diameter for stroke volume is measured at the annulus or within about 0.5 to 1 cm of it. The PW sample volume should be:","At the same level as the diameter measurement",["In the aorta","At the mitral tips","Deep in the LV apex"],"Mismatched sites cause stroke volume errors.","F"),
(M,"Measuring the LVOT diameter too small in an AS continuity calculation will:","Underestimate the aortic valve area",["Overestimate the valve area","Have no effect","Raise the peak velocity"],"The diameter is squared, so small errors matter a lot.","F"),
(M,"For PISA measurement of MR from the apical view, the color baseline is usually:","Shifted downward (in the direction of the jet) to lower the aliasing velocity to about 30–40 cm/s",["Shifted upward to 100 cm/s","Left at zero velocity","Removed"],"This gives a larger, easier-to-measure hemisphere.","C"),
(M,"For accurate Doppler velocity measurements, sweep speed is usually set at about:","100 mm/s",["10 mm/s","1 mm/s","500 mm/s"],"Faster sweeps spread the waveform for accurate timing measurements.","F"),
(M,"Aortic valve cusp separation on M-mode is reduced in:","Aortic stenosis or low cardiac output",["Aortic regurgitation only","High output states","Normal patients"],"Normal separation is about 1.5 to 2.6 cm.","C"),
(M,"The proximal RVOT diameter is measured in:","The PLAX view at end-diastole",["The A2C view","The subcostal IVC view","The suprasternal view"],"The distal RVOT is measured in PSAX just before the pulmonic valve.","F"),
(M,"The main pulmonary artery diameter is measured in:","The PSAX view at the level of the great vessels, between the valve and the bifurcation",["The apical two-chamber view","The PLAX view only","The subcostal view only"],"A dilated PA suggests pulmonary hypertension or a shunt.","F"),
(M,"Before reporting 3D LV volumes, the sonographer should check that:","The whole LV is inside the volume and there are no stitching artifacts",["The LV is foreshortened","Only one plane is used","No ECG is attached"],"3D EF is preferred when image quality allows.","F"),
(M,"LA appendage emptying velocity is measured with PW Doppler:","About 1 cm inside the appendage mouth on TEE",["In the pulmonary vein","In the LV apex","At the mitral tips"],"Low velocity (under about 20 cm/s) raises the risk of clot.","F"),
(M,"Which body surface area formula is commonly used in echo labs?","DuBois or Mosteller, using height and weight",["Age and heart rate","Blood pressure and weight","Height only"],"BSA is used to index chamber sizes and valve areas.","F"),
(M,"RVOT VTI is useful because a value under about 15 cm suggests:","Low RV stroke volume, a marker of poor prognosis in PH",["Normal RV output","Pulmonic stenosis","Normal PVR"],"It is also used in the PVR estimate.","C"),
(M,"Normal LVOT VTI is roughly 18–22 cm. A value of 10 cm suggests:","Low stroke volume and low cardiac output",["High output","Normal output","Aortic regurgitation only"],"It is a simple marker of forward flow in shock or heart failure.","F"),
(M,"When tracing the LA for volume, the border at the mitral valve is drawn:","Straight across the mitral annulus hinge points",["Through the tips of the open leaflets","Into the LV","Around the LAA"],"The LAA and pulmonary veins are left out.","F"),
(M,"In the PSAX view, planimetry of the aortic valve opening is best done:","At the leaflet tips in early systole, often with TEE",["At the annulus in diastole","In the LVOT","On M-mode"],"Heavy calcium makes planimetry unreliable.","C"),
(M,"For accurate measurements, Doppler gain should be set so that:","The spectral envelope is clear, with little background noise",["The whole screen is filled","The signal is barely visible","Noise is at maximum"],"High gain overestimates velocities.","F"),
# --- Stress echo extra ---
(S,"Atropine during DSE should be avoided in patients with:","Narrow-angle glaucoma or urinary retention from an enlarged prostate",["High blood pressure that is well controlled","Normal eye pressure","Diabetes only"],"Atropine can raise eye pressure and cause retention.","C"),
(S,"Hypotension during dobutamine infusion can be caused by:","Vasodilation or dynamic LVOT obstruction, not always ischemia",["Only multivessel disease","Normal response always","Aortic regurgitation only"],"Check for an LVOT gradient if BP drops.","C"),
(S,"Supine bicycle stress echo differs from treadmill testing because it:","Allows imaging and Doppler during exercise, not only after",["Is always done without ECG","Has no stages","Cannot raise heart rate"],"It is useful for measuring pressures and gradients at each stage.","F"),
(S,"A common side effect of dobutamine is:","Palpitations or extra beats",["Low heart rate","Rash in all patients","Hearing loss"],"Most side effects stop quickly when the infusion ends because dobutamine has a short half-life.","F"),
(S,"Why should images at peak stress be taken as quickly as possible after treadmill exercise?","Wall motion abnormalities can resolve within one to two minutes",["Heart rate rises after exercise","The patient needs to rest first","Images are always better later"],"Delays reduce sensitivity.","F"),
(S,"After a negative stress echo with adequate heart rate response, the patient's risk of a cardiac event in the next year is:","Low (under about 1% per year)",["Very high","The same as a positive test","Unknown in all cases"],"A normal stress echo has strong negative predictive value.","C"),
(S,"Stress echo for pulmonary pressure during exercise uses:","TR velocity at each stage to estimate RVSP",["LVOT VTI only","The aortic root","LV mass"],"Exercise-induced PH can explain shortness of breath.","F"),
(S,"A hypertensive response during exercise can cause:","Wall motion changes or false positives in some patients",["No changes ever","Lower heart rate","Pericardial effusion"],"Blood pressure is recorded at each stage.","C"),
(S,"An ischemic threshold refers to:","The heart rate or workload at which ischemia first appears",["The maximum dose of contrast","The lowest blood pressure","The first frame of an image"],"A low ischemic threshold suggests higher risk.","C"),
]
